23	 *     <li>已封存（UTC 日评估终态）的日期只记录迟到事件；</li>
24	 *     <li>实际温湿度连续 3 个采样点偏离当前生效策略的设定带，恰在第 3 点触发一次偏差告警。</li>
25	 * </ul>
26	 */
27	@Service
28	public class ReadingService {
29	
30	    /** 触发告警所需的连续偏离点数，恰为 3。 */
31	    static final int DEVIATION_RUN_TO_TRIGGER = 3;
32	    private static final int SCAN_WINDOW = 64;
33	
34	    private final ReadingRepository readingRepository;
35	    private final StrategyRepository strategyRepository;
36	    private final AlarmRepository alarmRepository;
37	    private final EvaluationRepository evaluationRepository;
38	    private final SetupService setupService;
39	    private final Clock clock;
40	
41	    public ReadingService(ReadingRepository readingRepository, StrategyRepository strategyRepository,
42	                          AlarmRepository alarmRepository, EvaluationRepository evaluationRepository,
43	                          SetupService setupService, Clock clock) {
44	        this.readingRepository = readingRepository;
45	        this.strategyRepository = strategyRepository;
46	        this.alarmRepository = alarmRepository;
47	        this.evaluationRepository = evaluationRepository;
48	        this.setupService = setupService;
49	        this.clock = clock;
50	    }
51	
52	    @Transactional
53	    public ReadingDtos.ReadingResponse ingest(ReadingDtos.ReadingRequest request) {
54	        setupService.requireZone(request.zoneCode());
55	        Instant now = clock.instant();
56	        LocalDate utcDate = request.sampleTime().atZone(ZoneOffset.UTC).toLocalDate();
57	
58	        // 封存为终态：迟到读数只记迟到事件，不参与评估与告警。
59	        if (evaluationRepository.isSealed(request.zoneCode(), utcDate)) {
60	            readingRepository.recordLate(request.zoneCode(), request.sampleTime(),
61	                    request.temperature(), request.humidity(), now);
62	            return new ReadingDtos.ReadingResponse(request.zoneCode(), request.sampleTime(),
63	                    request.temperature(), request.humidity(), false, true, null);
64	        }
65	
66	        try {
67	            readingRepository.insert(request.zoneCode(), request.sampleTime(),
68	                    request.temperature(), request.humidity(), now);
69	        } catch (DuplicateKeyException e) {
70	            // 同分区同时刻重复上报：幂等去重，不重复检测、不重复告警。
71	            return new ReadingDtos.ReadingResponse(request.zoneCode(), request.sampleTime(),
72	                    request.temperature(), request.humidity(), true, false, null);
73	        }
74	
75	        Long alarmId = detectDeviation(request.zoneCode(), request.sampleTime(), now);
76	        return new ReadingDtos.ReadingResponse(request.zoneCode(), request.sampleTime(),
77	                request.temperature(), request.humidity(), false, false, alarmId);
78	    }
79	
80	    /**
81	     * 以该分区最新一个采样点为末端（乱序补点会改变末端），沿采样时刻向前统计在同一策略下
82	     * 连续偏离设定带的点数；恰在连续点数达到 3 且此前无同起点告警时产生一条告警。
83	     * 这样乱序上报按时刻归位后重算，触发时刻为本次入库时刻，起点为连续序列首个采样时刻。
84	     */
85	    private Long detectDeviation(String zoneCode, Instant ingestedSampleTime, Instant now) {
86	        // 乱序补点时末端仍是分区最新采样点，因此以全分区最大采样时刻（而非本次入库时刻）取窗。
87	        Instant latestTime = readingRepository.findLatestSampleTime(zoneCode);
88	        if (latestTime == null) {
89	            return null;
90	        }
91	        List<ReadingRepository.Reading> recent =
92	                readingRepository.findRecentUntil(zoneCode, latestTime, SCAN_WINDOW);
93	        if (recent.isEmpty()) {
94	            return null;
95	        }
96	        ReadingRepository.Reading latest = recent.get(recent.size() - 1);
97	        StrategyRepository.Strategy strategy =
98	                strategyRepository.findEffectiveAt(zoneCode, latest.sampleTime()).orElse(null);
99	        if (strategy == null || !isOutOfBand(strategy, latest)) {
100	            return null;
101	        }
102	        int runLength = 0;
103	        Instant runStart = null;
104	        for (int i = recent.size() - 1; i >= 0; i--) {
105	            ReadingRepository.Reading r = recent.get(i);
106	            StrategyRepository.Strategy effective =
107	                    strategyRepository.findEffectiveAt(zoneCode, r.sampleTime()).orElse(null);
108	            if (effective == null || !effective.id().equals(strategy.id()) || !isOutOfBand(strategy, r)) {
109	                break;
110	            }
111	            runLength++;
112	            runStart = r.sampleTime();
113	        }
114	        if (runLength != DEVIATION_RUN_TO_TRIGGER) {
115	            return null;
116	        }
117	        if (alarmRepository.existsWithStart(zoneCode, strategy.strategyCode(), runStart)) {
118	            return null;
119	        }
120	        return alarmRepository.insert(zoneCode, strategy.strategyCode(), runStart, latest.sampleTime(),
121	                runLength, now);
122	    }
123	
124	    /**
125	     * 偏离设定带：温度落在白天/夜间任一设定点允许带之外，或湿度超出设定点允许带宽。恰在边界视为带内。
126	     */
127	    public static boolean isOutOfBand(StrategyRepository.Strategy s, ReadingRepository.Reading r) {
128	        BigDecimal temp = r.temperature();
129	        boolean tempInBand = inTolerance(temp, s.dayTemp(), s.tempTolerance())
130	                || inTolerance(temp, s.nightTemp(), s.tempTolerance());
131	        boolean humidityInBand = inTolerance(r.humidity(), s.humiditySetpoint(), s.humidityTolerance());
132	        return !tempInBand || !humidityInBand;
133	    }
134	
135	    private static boolean inTolerance(BigDecimal actual, BigDecimal setpoint, BigDecimal tolerance) {
136	        return actual.subtract(setpoint).abs().compareTo(tolerance) <= 0;
137	    }
