15	import static org.assertj.core.api.Assertions.assertThat;
16	
17	/**
18	 * 日评估：SEALED 终态幂等、迟到读数不改变结果、设定达成率与能耗明细可复算、并发封存唯一成功。
19	 */
20	class DailyEvaluationTest extends AbstractIntegrationTest {
21	
22	    private static final LocalDate DAY = LocalDate.of(2026, 1, 6);
23	    private static final Instant T0 = DAY.atStartOfDay(java.time.ZoneOffset.UTC).toInstant();
24	
25	    @BeforeEach
26	    void setUp() {
27	        seedZone();
28	        seedCrop();
29	        allocateBudget(DAY.toString(), "10.000");
30	        draftStrategy("S1", "24.00", "18.00", "70.00", "1.0", "5.0");
31	        dispatch("S1", "REQ-D", T0);
32	    }
33	
34	    @Test
35	    @DisplayName("封存输出达成率与能耗明细；重复封存幂等返回首次结果且 replayed=true；迟到读数不改变封存值")
36	    void sealIsTerminalAndReplayable() {
37	        // 3 点在带内（含边界 25.0℃、湿度 75%RH），1 点偏离：达成率 0.75。
38	        ingest(T0, "24.00", "70");
39	        ingest(T0.plusSeconds(60), "25.00", "70");
40	        ingest(T0.plusSeconds(120), "25.01", "70");
41	        ingest(T0.plusSeconds(180), "24.00", "75");
42	
43	        energyService.issueCommand(new CommandDtos.CommandRequest(
44	                "CMD-H", ZONE, "HEAT", bd("6.000"), T0.plusSeconds(10)));
45	        energyService.issueCommand(new CommandDtos.CommandRequest(
46	                "CMD-L", ZONE, "SUPPLEMENT_LIGHT", bd("2.000"), T0.plusSeconds(20)));
47	        energyService.issueCommand(new CommandDtos.CommandRequest(
48	                "CMD-V", ZONE, "VENTILATE", null, T0.plusSeconds(30)));
49	
50	        EvaluationDtos.EvaluationResponse first = evaluationService.seal(
51	                new EvaluationDtos.EvaluationRequest(ZONE, DAY));
52	        assertThat(first.status()).isEqualTo("SEALED");
53	        assertThat(first.replayed()).isFalse();
54	        assertThat(first.inBandCount()).isEqualTo(3);
55	        assertThat(first.totalCount()).isEqualTo(4);
56	        assertThat(first.achievementRate()).isEqualByComparingTo("0.7500");
57	        assertThat(first.budgetKwh()).isEqualByComparingTo("10.000");
58	        assertThat(first.consumedKwh()).isEqualByComparingTo("8.000");
59	
60	        Map<String, EvaluationDtos.EnergyItem> detail = new java.util.HashMap<>();
61	        first.energyDetail().forEach(i -> detail.put(i.commandType(), i));
62	        assertThat(detail.get("HEAT").commandCount()).isEqualTo(1);
63	        assertThat(detail.get("HEAT").energyKwh()).isEqualByComparingTo("6.000");
64	        assertThat(detail.get("SUPPLEMENT_LIGHT").energyKwh()).isEqualByComparingTo("2.000");
65	        assertThat(detail.get("VENTILATE").energyKwh()).isEqualByComparingTo("0.000");
66	
67	        // 封存后迟到读数只记迟到事件。
68	        assertThat(ingest(T0.plusSeconds(900), "5.00", "5").late()).isTrue();
69	
70	        EvaluationDtos.EvaluationResponse replay = evaluationService.seal(
